DISCOVERY_TRANSLATIONS: dict[str, dict[str, str]] = {
    locale: dict(zip(DISCOVERY_KEYS, row.split("|"), strict=True))
    for locale, row in DISCOVERY_ROWS.items()
}

if len(set(DISCOVERY_KEYS)) != len(DISCOVERY_KEYS) or len(
    set(DISCOVERY_LOCALES)
) != len(DISCOVERY_LOCALES):
    raise ValueError(
        "Events discovery catalog manifests must not contain duplicates"
    )
if set(DISCOVERY_ROWS) != set(DISCOVERY_LOCALES):
    raise ValueError(
        "Events discovery catalog locales do not match the manifest"
    )
if any(
    set(entries) != set(DISCOVERY_KEYS)
    for entries in DISCOVERY_TRANSLATIONS.values()
):
    raise ValueError("Events discovery catalog keys do not match the manifest")
if any(
    not value.strip()
    for entries in DISCOVERY_TRANSLATIONS.values()
    for value in entries.values()
):
    raise ValueError("Events discovery catalog entries must be non-empty")
if any(
    "1000" not in entries["Show events up to 1000 kilometres away"]
    for entries in DISCOVERY_TRANSLATIONS.values()
):
    raise ValueError(
        "Events discovery distance boundary must remain 1000 kilometres"
    )
